def A(intervals):
    result = []
    for start, end in sorted(intervals):
        if result and start <= result[-1][1]:
            result[-1][1] = max(result[-1][1], end)
        else:
            result.append([start, end])
    return result

def B(interval, point):
    return interval[0] <= point <= interval[1]

def C(window, blocked):
    result = []
    current = window[0]
    for start, end in A(blocked):
        if start > current:
            result.append([current, start])
        current = max(current, end)
    if current < window[1]:
        result.append([current, window[1]])
    return result

