def A(values):
    result = []
    for value in values:
        if value not in result:
            result.append(value)
    return result

def B(values, count):
    return values[-count:]

def C(shards):
    result = {}
    for shard in shards:
        for key, value in shard.items():
            result[key] = result.get(key, 0) + value
    return result

